import React from 'react';
import axios from 'axios';

const ClienteList = ({ clientes }) => {
  const handleDelete = (id) => {
    // Envia a requisição para excluir o cliente
    axios.delete(`/clientes/${id}`)
      .then(() => {
        // Atualiza a lista de clientes após a exclusão
        alert('Cliente excluído com sucesso!');
      })
      .catch(error => {
        console.error("Erro ao excluir cliente", error);
      });
  };

  return (
    <div>
      <h2>Lista de Clientes</h2>
      <ul>
        {clientes.map(cliente => (
          <li key={cliente.id}>
            <div>
              <strong>{cliente.nome}</strong> - {cliente.email} - {cliente.telefone}
              <button onClick={() => handleDelete(cliente.id)} style={{ marginLeft: "10px" }}>Excluir</button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ClienteList;
